function hintFor(beatId, costShown) {
  switch (beatId) {
    case 'apollo':
      return costShown ? 'Next: Spacecraft emergency' : 'Next: Show the cost'
    case 'cost':
      return 'Next: Spacecraft emergency'
    case 'emergency':
      return 'Next: FLARE'
    case 'flare':
      return 'Next: Scenario and comparison'
    case 'compare':
      return 'Next: Visualization'
    case 'visualize':
      return 'Next: SI assistant'
    case 'assistant':
      return 'Next: Our team'
    default:
      return 'End of presentation'
  }
}

const SLIDE_GROUPS = Array.from({ length: SLIDE_COUNT }, (_, i) => i + 1).map((slide) => ({
  slide,
  beats: BEATS.map((b, i) => (b.slide === slide ? i : -1)).filter((i) => i >= 0),
}))

function enterBeat(n, index, mode) {
  const timeline = TIMELINES[BEATS[index].id]
  return { index, mode, phase: mode === 'end' ? timeline.length - 1 : 0, token: n.token + 1, costShown: false, focus: 'screen' }
}

// ============================================================================
// Geometry (16:9 stage, 1600 x 900 user units)
// ============================================================================

const W = 1600
const H = 900
const CX = W / 2
const CY = H / 2
const STATION = { x: 800, y: 300 }
const PORT = { x: 70, y: -4, r: 16 } // the station window the camera dives into, station coordinates
const DIVE = { x: STATION.x + PORT.x, y: STATION.y + PORT.y }
const FIRE = { x: 1182, y: 534 } // flame source on the equipment rack, cabin coordinates
const SCREEN = { x: 302, y: 340, w: 190, h: 122 } // the workstation laptop screen, cabin coordinates
const SITE_VIEW = { w: 1440, h: 925 } // the website's own viewport inside that screen, CSS px
const PORTRAIT = { w: 300, h: 375, gap: 70, y: 186 }
const COST_Y = 652
const WORD = { size: 170, tracking: 0.14, baseline: 505, lift: 70, markR: 52, markGap: 34, markScale: 1.7 }
const ESTIMATED_TEXT_WIDTH = 680

// The team logo image (1073 x 743), measured: its ring, the shooting star with its trails, and
// the twelve letters of COSMIC SHIHAB. Masks cut the one image into these parts; nothing is redrawn.
const LOGO = { w: 1073, h: 743 }
const RING = { cx: 544, cy: 310, rx: 250, ry: 239, band: 64 }
// The ring's centre line, starting at the top and running clockwise, so the pen starts at 12 o'clock.
const RING_PATH = `M${RING.cx} ${RING.cy - RING.ry} A${RING.rx} ${RING.ry} 0 1 1 ${RING.cx} ${RING.cy + RING.ry} A${RING.rx} ${RING.ry} 0 1 1 ${RING.cx} ${RING.cy - RING.ry}`
const SHOOTING_STAR = 'M170 45 L360 95 L560 185 L700 330 L760 410 L860 470 L860 505 L760 520 L722 605 L690 605 L668 520 L560 450 L440 330 L330 215 L220 165 L170 120 Z'
const WORDMARK = { y: 606, h: 90 }
const LETTERS = [[51, 111], [137, 209], [234, 284], [312, 380], [413, 422], [452, 512], [568, 618], [647, 703], [736, 745], [777, 834], [865, 937], [967, 1024]]
const LOGO_AT = { s: 0.62, x: CX - (1073 * 0.62) / 2, y: 440 - (743 * 0.62) / 2 }
// Final layout: the logo moves 239 left and the QR card sits 90 to its right, so the pair is centred.
// The card's white margin gives the code a quiet zone of about four modules, for phone cameras.
const QR_AT = { x: 1018, y: 232, size: 320, pad: 34, cx: 1178, shift: -239 }
// The challenge and the members, centred under the pair, above the presenter's controls.
const CREDITS_AT = { x: CX, y: 724, line: 34 }

const portraitX = (i) => CX - (PORTRAIT.w * 3 + PORTRAIT.gap * 2) / 2 + i * (PORTRAIT.w + PORTRAIT.gap)
const cam = (x, y, s) => `translate(${CX - x * s}px, ${CY - y * s}px) scale(${s})`
const camOf = (c) => cam(c.x, c.y, c.s)
const at = (x, y, s) => `translate(${x}px, ${y}px) scale(${s})`
const IDENTITY = cam(CX, CY, 1)
const pivot = (deg, x, y) => `translate(${x}px, ${y}px) rotate(${deg}deg) translate(${-x}px, ${-y}px)`

function markLayout(textWidth) {
  const visible = Math.max(0, textWidth - WORD.tracking * WORD.size) // drop the tracking after the last letter
  const total = WORD.markR * 2 + WORD.markGap + visible
  const left = CX - total / 2
  return { markX: left + WORD.markR, markY: WORD.baseline - 0.35 * WORD.size, textX: left + WORD.markR * 2 + WORD.markGap }
}

// ============================================================================
// Phases: cameras, fire stages and lighting
// ============================================================================

const SPACEWARD = new Set(['apollo', 'cost', 'space', 'station'])
const CABIN = new Set(['interior', 'fire', 'notice', 'alarm', 'closer', 'danger', 'desk', 'screen', 'pullback'])
const SITE = new Set(['desk', 'screen', 'pullback'])
const AMBER = new Set(['notice', 'alarm', 'closer', 'danger'])
const RED = new Set(['alarm', 'closer', 'danger'])
const LOGO_PHASES = new Set(['reveal', 'name'])
const TEAM = ['warp', 'ring', 'star', 'logo', 'letters', 'qr']

const CABIN_CAMERAS = {
  hidden: { x: CX, y: CY, s: 1.18 }, // before the dive lands
  wide: { x: CX, y: CY, s: 1 },
  alarm: { x: 1000, y: 480, s: 1.15 },
  closer: { x: 1060, y: 500, s: 1.6 },
  danger: { x: 1080, y: 506, s: 1.95 },
  dive: { x: FIRE.x, y: FIRE.y, s: 2.9 }, // keeps pushing into the flame while the cabin goes dark
  warp: { x: CX, y: CY, s: 0.035 }, // rushed away to a point
}

/**
 * Where the camera looks on the laptop screen: a point of the website's own view (fractions of
 * its width and height) and a zoom. 'screen' fills the frame with the whole site; the others
 * move in on the part of the real page the slide is talking about.
 */
const FOCUS = {
  screen: { fx: 0.5, fy: 0.5, s: 7 },
  form: { fx: 0.4, fy: 0.5, s: 8.4 }, // the Scenario form
  lanes: { fx: 0.67, fy: 0.6, s: 10 }, // the comparison, condition by condition
  chart: { fx: 0.5, fy: 0.55, s: 8.6 }, // a Visualization chart
  answer: { fx: 0.45, fy: 0.52, s: 8.4 }, // the assistant's answer
}
const screenCamera = (focus) => {
  const f = FOCUS[focus] || FOCUS.screen
  return { x: SCREEN.x + f.fx * SCREEN.w, y: SCREEN.y + f.fy * SCREEN.h, s: f.s }
}

/** k: flame size; spread: how far it has run along the rack with the airflow; embers; heat glow. */
const FIRE_STAGES = {
  fire: { k: 0.9, spread: 0, embers: 0, heat: 0.25 },
  notice: { k: 1.25, spread: 0, embers: 0, heat: 0.5 },
  alarm: { k: 1.45, spread: 0.55, embers: 0.45, heat: 0.75 },
  closer: { k: 1.6, spread: 0.85, embers: 1, heat: 0.9 },
  danger: { k: 1.75, spread: 1, embers: 1, heat: 1 },
}
const SMOKE_SPREAD = { notice: 0.6, alarm: 1, closer: 1.25, danger: 1.45 }
const FIRELIGHT = { fire: 0.35, notice: 0.6, alarm: 0.8, closer: 0.9, danger: 1 }
// The cabin lights fail as the emergency grows, so the fire and the red beacons carry the scene.
const DIM = { notice: 0.08, alarm: 0.28, closer: 0.4, danger: 0.5 }

/** Camera move durations (ms) into each phase. */
const CAMERA_MS = { apollo: 1400, cost: 1400, space: 1200, station: 2200, interior: 1800, fire: 1000, notice: 1100, alarm: 1900, closer: 2000, danger: 2300, reveal: 1300, name: 1200, desk: 1800, screen: 2600, pullback: 2400, warp: 1400 }

/** Reduced motion: one fixed framing per shot, and a short dip to navy when the shot changes. */
const SHOT = { apollo: 'apollo', cost: 'apollo', space: 'space', station: 'space', interior: 'cabin', fire: 'cabin', notice: 'cabin', alarm: 'close', closer: 'close', danger: 'close', reveal: 'logo', name: 'logo', desk: 'desk', screen: 'screen', pullback: 'desk', warp: 'team', ring: 'team', star: 'team', logo: 'team', letters: 'team', qr: 'team' }
const REDUCED_FRAMING = { space: 'station', close: 'closer' }

function cabinCamera(frame, focus) {
  if (frame === 'interior' || frame === 'fire' || frame === 'notice' || frame === 'desk' || frame === 'pullback') return CABIN_CAMERAS.wide
  if (frame === 'alarm' || frame === 'closer' || frame === 'danger') return CABIN_CAMERAS[frame]
  if (frame === 'screen') return screenCamera(focus)
  if (TEAM.includes(frame)) return CABIN_CAMERAS.warp
  if (SPACEWARD.has(frame)) return CABIN_CAMERAS.hidden
  return CABIN_CAMERAS.dive
}

function exteriorCamera(frame, which) {
  const far = frame === 'apollo' || frame === 'cost' || frame === 'space'
  if (which === 'stars') return SPACEWARD.has(frame) ? IDENTITY : cam(DIVE.x, DIVE.y, 1.35)
  if (which === 'earth') return far ? cam(CX, CY - 300, 1) : frame === 'station' ? IDENTITY : cam(DIVE.x, DIVE.y, 1.9)
  return far ? cam(STATION.x, STATION.y + 40, 0.42) : frame === 'station' ? IDENTITY : cam(DIVE.x, DIVE.y, 12)
}

function flamePlacement(id, layout, c) {
  const stage = FIRE_STAGES[id]
  if (stage) {
    // The cabin camera's own transform applied to the flame source, so the two stay registered.
    return { x: CX + (FIRE.x - c.x) * c.s, y: CY + (FIRE.y - c.y) * c.s, s: stage.k * c.s, o: 1 }
  }
  if (id === 'reveal') return { x: layout.markX, y: layout.markY, s: WORD.markScale, o: 1 }
  if (id === 'name') return { x: layout.markX, y: layout.markY - WORD.lift, s: WORD.markScale, o: 1 }
  return { x: FIRE.x, y: FIRE.y, s: 0.12, o: 0 } // not lit, or out: hidden at its source
}

function fade(visible, { inMs = TIMING.reveal, outMs = TIMING.reveal, inDelay = 0, outDelay = 0 } = {}, extra = '') {
  const parts = visible
    ? [`opacity ${inMs}ms ease-in-out ${inDelay}ms`, 'visibility 0ms linear 0ms']
    : [`opacity ${outMs}ms ease-in-out ${outDelay}ms`, `visibility 0ms linear ${outDelay + outMs}ms`]
  if (extra) parts.unshift(extra)
  return { opacity: visible ? 1 : 0, visibility: visible ? 'visible' : 'hidden', transition: parts.join(', ') }
}

/** Every story-layer style for one phase. Pure: the same phase and focus always give the same picture. */
function deriveScene(id, { layout, reduced, costShown, focus }) {
  const ms = CAMERA_MS[id] || 1400
  const curve = id === 'warp' ? 'cubic-bezier(0.55, 0, 1, 0.45)' : TIMING.ease // the warp accelerates away
  const move = (d = ms) => (reduced ? 'transform 0ms linear 330ms' : `transform ${d}ms ${curve}`)
  const frame = reduced ? REDUCED_FRAMING[SHOT[id]] || id : id
  const onApollo = id === 'apollo' || id === 'cost'
  const costVisible = id === 'cost' || (id === 'apollo' && costShown)
  const inCabin = CABIN.has(id)
  const red = RED.has(id)
  const stage = FIRE_STAGES[id]
  const camera = cabinCamera(frame, reduced ? 'screen' : focus)
  const f = flamePlacement(id, layout, camera)
  const t = TEAM.indexOf(id)
  const warpOut = fade(false, { outMs: 500, outDelay: reduced ? 0 : 900 })
  // Leaving slide 7, its parts snap back only once the whole team layer has faded out.
  const reset = (...props) => props.map((p) => `${p} 0ms linear 520ms`).join(', ')
  const shrink = 0.86
  const costStart = 0.92
  const qrStart = 0.9
  return {
    pose: id === 'notice' ? 'noticing' : red ? 'bracing' : 'working',
    shake: reduced ? 0 : id === 'danger' ? 1 : id === 'closer' ? 0.55 : 0,
    costVisible,
    apollo: fade(onApollo, { inMs: 1200, outMs: 1100 }),
    apolloShift: {
      transform: costVisible ? `translate(${CX * (1 - shrink)}px, ${PORTRAIT.y * (1 - shrink) - 40}px) scale(${shrink})` : 'translate(0px, 0px) scale(1)',
      transition: reduced ? 'none' : `transform 1400ms ${TIMING.ease}`,
    },
    cost: {
      ...fade(costVisible, { inMs: 1100, inDelay: reduced ? 0 : 350, outMs: 500 }, reduced ? '' : `transform 1600ms ${TIMING.ease}`),
      transform: costVisible ? 'translate(0px, 0px) scale(1)' : `translate(${CX * (1 - costStart)}px, ${COST_Y * (1 - costStart)}px) scale(${costStart})`,
    },
    stars: { ...fade(SPACEWARD.has(id), { inMs: 1000, outMs: 900, outDelay: reduced ? 0 : 600 }, move()), transform: exteriorCamera(frame, 'stars') },
    exterior: fade(id === 'space' || id === 'station', { inMs: 1600, inDelay: id === 'space' && !reduced ? 500 : 0, outMs: 900, outDelay: id === 'interior' && !reduced ? 600 : 0 }),
    earth: { transform: exteriorCamera(frame, 'earth'), transition: move() },
    station: { transform: exteriorCamera(frame, 'station'), transition: move() },
    interior: id === 'warp' ? warpOut : fade(inCabin, { inMs: 1000, inDelay: reduced ? 0 : 500, outMs: LOGO_PHASES.has(id) ? 900 : 500 }),
    interiorCam: { transform: camOf(camera), transition: move() },
    screen: id === 'warp' ? warpOut : fade(SITE.has(id), { inMs: 1000, inDelay: reduced ? 0 : 500, outMs: 600 }),
    amber: fade(AMBER.has(id), { inMs: 500, outMs: 400 }),
    red: fade(red, { inMs: 700, outMs: 400 }),
    smoke: fade(AMBER.has(id), { inMs: 1800, outMs: 700 }),
    spread: { transform: `scale(${SMOKE_SPREAD[id] || 0.5})`, transition: reduced ? 'none' : `transform 3000ms ${TIMING.ease}` },
    haze: fade(id === 'closer' || id === 'danger', { inMs: 2600, outMs: 700 }),
    firelight: { opacity: FIRELIGHT[id] || 0, transition: 'opacity 1500ms ease-in-out' },
    dim: { opacity: DIM[id] || 0, transition: 'opacity 2400ms ease-in-out' },
    vignette: { opacity: id === 'danger' ? 1 : id === 'closer' ? 0.6 : 0, transition: 'opacity 2200ms ease-in-out' },
    flame: {
      transform: at(f.x, f.y, f.s),
      opacity: f.o,
      visibility: f.o ? 'visible' : 'hidden',
      transition: [move(), `opacity ${TIMING.reveal}ms ease-in-out`, `visibility 0ms linear ${f.o ? 0 : TIMING.reveal}ms`].join(', '),
    },
    heat: { opacity: stage ? stage.heat : 0, transition: 'opacity 2000ms ease-in-out' },
    fireSpread: {
      opacity: stage && stage.spread ? 1 : 0,
      transform: stage && stage.spread ? `scale(${stage.spread}, ${0.55 + 0.45 * stage.spread})` : 'scale(0.15, 0.5)',
      transition: `transform 2600ms ${TIMING.ease}, opacity 1400ms ease-in-out`,
    },
    embers: { opacity: stage ? stage.embers : 0, transition: 'opacity 1500ms ease-in-out' },
    backdrop: fade(LOGO_PHASES.has(id), { inMs: 1400, inDelay: id === 'reveal' && !reduced ? 600 : 0, outMs: 600 }),
    lift: { transform: id === 'name' ? `translate(0px, ${-WORD.lift}px)` : 'translate(0px, 0px)', transition: move() },
    wordmark: fade(LOGO_PHASES.has(id), { inMs: 700, inDelay: 150, outMs: 450 }),
    subtitle: fade(id === 'name', { inMs: 700, inDelay: 300, outMs: 350 }),
    tagline: fade(id === 'name', { inMs: 700, inDelay: 700, outMs: 350 }),
    team: fade(t >= 1, { inMs: 300, outMs: 500 }),
    // The ring draws itself from the top, clockwise, like a pen.
    ringPen: {
      strokeDashoffset: t >= 1 ? 0 : 1,
      transition: t < 1 ? reset('stroke-dashoffset') : reduced ? 'none' : 'stroke-dashoffset 1700ms cubic-bezier(0.45, 0, 0.25, 1)',
    },
    // The shooting star falls in from above the frame and settles into its place on the ring.
    logoStar: {
      opacity: t >= 2 ? 1 : 0,
      transform: t >= 2 || reduced ? 'translate(0px, 0px)' : 'translate(0px, -1000px)',
      transition: t >= 2 ? 'transform 1300ms cubic-bezier(0.16, 1, 0.3, 1), opacity 250ms ease-out' : reset('transform', 'opacity'),
    },
    logoRest: fade(t >= 3, { inMs: 700, outMs: 0, outDelay: 520 }),
    letters: LETTERS.map((_, i) => ({
      opacity: t >= 4 ? 1 : 0,
      transform: t >= 4 || reduced ? 'translate(0px, 0px)' : 'translate(0px, 14px)',
      transition: t >= 4 ? `opacity 420ms ease-out ${i * 110}ms, transform 520ms ${TIMING.ease} ${i * 110}ms` : reset('opacity', 'transform'),
    })),
    teamShift: {
      transform: t >= 5 ? `translate(${QR_AT.shift}px, 0px)` : 'translate(0px, 0px)',
      transition: t < 5 ? reset('transform') : reduced ? 'none' : `transform 1200ms ${TIMING.ease}`,
    },
    qr: {
      ...(t >= 5
        ? fade(true, { inMs: 900, inDelay: reduced ? 0 : 400 }, reduced ? '' : `transform 1100ms ${TIMING.ease} 400ms`)
        : fade(false, { outMs: 0, outDelay: 520 }, reset('transform'))),
      transform: t >= 5 ? 'translate(0px, 0px) scale(1)' : `translate(${QR_AT.cx * (1 - qrStart)}px, ${(QR_AT.y + QR_AT.size / 2) * (1 - qrStart)}px) scale(${qrStart})`,
    },
    // The challenge and the members settle in once the QR card has arrived.
    credits: fade(t >= 5, { inMs: 900, inDelay: reduced ? 0 : 1100, outMs: 0, outDelay: 520 }),
  }
}

// ============================================================================
// Deterministic scenery (seeded, so a re-render never reshuffles it)
// ============================================================================

function seeded(seed) {
  let s = seed >>> 0
  return () => {
    s = (s + 0x6d2b79f5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function starField(seed, count, [rMin, rMax], [oMin, oMax]) {
  const r = seeded(seed)
  return Array.from({ length: count }, () => ({
    x: r() * W,
    y: r() * H,
    r: rMin + r() * (rMax - rMin),
    o: oMin + r() * (oMax - oMin),
    twinkle: r() < 0.25,
    d: 2.4 + r() * 3.6,
    delay: -r() * 6,
  }))
}

const STAR_LAYERS = [
  { stars: starField(7, 90, [0.6, 1.1], [0.35, 0.7]), seconds: 420 },
  { stars: starField(11, 45, [1, 1.6], [0.45, 0.85]), seconds: 300 },
  { stars: starField(19, 16, [1.5, 2.2], [0.6, 0.95]), seconds: 200 },
]
const BACKDROP_STARS = starField(23, 70, [0.6, 1.4], [0.3, 0.7])

const EARTH_FEATURES = (() => {
  const r = seeded(42)
  const land = Array.from({ length: 26 }, () => ({ cloud: false, a: r() * 360, rho: 990 + r() * 130, rx: 70 + r() * 150, ry: 26 + r() * 50, tilt: r() * 40 - 20 }))
  const clouds = Array.from({ length: 40 }, () => ({ cloud: true, a: r() * 360, rho: 1000 + r() * 135, rx: 50 + r() * 140, ry: 8 + r() * 14, tilt: r() * 20 - 10 }))
  return [...land, ...clouds]
})()

const TRUSS = Array.from({ length: 41 }, (_, i) => `${i === 0 ? 'M' : 'L'}${-400 + i * 20} ${i % 2 ? 8 : -8}`).join(' ')

// Smoke does not rise here: each puff spreads around the source and drifts sideways
// with the cabin airflow, up or down only a little.
