const EMBERS = Array.from({ length: 12 }, (_, i) => {
  const r = seeded(70 + i)
  return { x: -20 - r() * 60, y: -14 + r() * 28, r: 1.6 + r() * 1.6, d: 1.5 + r() * 1.4, delay: -r() * 2.5, ex: -(160 + r() * 140), ey: -24 + r() * 48 }
})

// Slide 7: as the camera rushes away, stars stretch into streaks racing toward the vanishing
// point. Every streak is done within the warp's 1.5 s.
const STREAKS = Array.from({ length: 80 }, (_, i) => {
  const r = seeded(300 + i)
  return { a: r() * 360, from: 560 + r() * 520, len: 40 + r() * 90, w: 1 + r() * 2, d: 0.7 + r() * 0.45, delay: 0.1 + r() * 0.25, o: 0.45 + r() * 0.55 }
})

