class Cancelled extends Error {}

/**
 * Drives the real site in the frame. Same-origin, it uses the site's own pages exactly as a
 * visitor would: it navigates through the site's router, types into its fields and presses its
 * buttons. Cross-origin it can only load pages by their links. It never draws or invents content.
 */
function makeDriver({ frame, base, sameOrigin, alive }) {
  const check = () => {
    if (!alive()) throw new Cancelled()
  }
  const sleep = (ms) => new Promise((resolve, reject) => window.setTimeout(() => (alive() ? resolve() : reject(new Cancelled())), ms))
  const view = () => {
    const f = frame()
    return f ? f.contentWindow : null
  }
  const path = () => {
    try {
      const w = view()
      return w ? w.location.pathname + w.location.search : null
    } catch {
      return null
    }
  }
  const loaded = () =>
    new Promise((resolve) => {
      const f = frame()
      if (!f) return resolve()
      const done = () => {
        f.removeEventListener('load', done)
        resolve()
      }
      f.addEventListener('load', done)
      window.setTimeout(done, 9000)
    })
  async function go(target) {
    check()
    const f = frame()
    if (!f) return
    if (sameOrigin) {
      const w = f.contentWindow
      const routed = w && w.location.href !== 'about:blank' && w.document.getElementById('root')
      if (routed) {
        if (path() !== target) {
          w.history.pushState({}, '', target) // the site's router follows popstate like a link click
          w.dispatchEvent(new w.PopStateEvent('popstate', { state: {} }))
          await sleep(400)
        }
        w.scrollTo(0, 0)
        return
      }
      const wait = loaded()
      f.src = base + target
      await wait
      check()
      return
    }
    const wait = loaded()
    f.src = base + target
    await wait
    check()
  }
  async function find(selector, { timeout = 8000, text, nth = 0 } = {}) {
    if (!sameOrigin) return null
    const started = Date.now()
    while (Date.now() - started < timeout) {
      check()
      const w = view()
      const doc = w && w.document
      if (doc) {
        const all = [...doc.querySelectorAll(selector)]
        const el = text ? all.find((e) => e.textContent.trim().startsWith(text)) : all[nth]
        if (el) return el
      }
      await sleep(120)
    }
    return null
  }
  function setValue(el, value) {
    if (!el) return
    const w = el.ownerDocument.defaultView
    const proto = el.tagName === 'TEXTAREA' ? w.HTMLTextAreaElement.prototype : w.HTMLInputElement.prototype
    Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, value) // the setter React listens through
    el.dispatchEvent(new w.Event('input', { bubbles: true }))
  }
  async function type(el, text, perChar = 70) {
    if (!el) return
    setValue(el, '')
    for (const ch of text) {
      setValue(el, el.value + ch)
      await sleep(perChar)
    }
    el.dispatchEvent(new el.ownerDocument.defaultView.Event('change', { bubbles: true }))
  }
  function click(el) {
    if (!el) return
    el.click()
    const f = frame()
    if (f && document.activeElement === f) f.blur() // keep the presenter's keys on the slides
  }
  async function scrollTo(el, offset = 120) {
    if (!el) return
    const w = el.ownerDocument.defaultView
    const root = el.ownerDocument.documentElement
    const target = () => Math.max(0, Math.min(el.getBoundingClientRect().top + w.scrollY - offset, root.scrollHeight - w.innerHeight))
    w.scrollTo({ top: target(), behavior: 'smooth' })
    await sleep(750)
    if (Math.abs(w.scrollY - target()) > 40) {
      // The page was still laying out (charts arriving): aim again.
      w.scrollTo({ top: target(), behavior: 'smooth' })
      await sleep(600)
    }
  }
  return { sameOrigin, sleep, go, find, setValue, type, click, scrollTo, path }
}

/** The real Comparison page compares its top two investigations; the demo adds the third. */
async function addThird(d) {
  const box = await d.find('.ranked-row input[type="checkbox"]', { nth: 2, timeout: 12000 })
  if (box && !box.checked) d.click(box)
  await d.sleep(400)
  await d.scrollTo(await d.find('h2', { text: 'Ranked' }), 90)
}

/** One demo per website slide. `end` jumps straight to the slide's finished state. */
const SITE_DEMOS = {
  async compare(d, setPhase, end) {
    if (end) {
      setPhase('screen', 'lanes')
      if (!(d.path() || '').startsWith('/comparison')) await d.go(DEMO.comparisonPath)
      await addThird(d)
      return
    }
    setPhase('desk')
    if (d.path() !== '/') await d.go('/')
    await d.sleep(1700)
    setPhase('screen', 'screen')
    await d.sleep(2600)
    if (!d.sameOrigin) {
      await d.go(DEMO.comparisonPath)
      return
    }
    await d.go('/scenario')
    setPhase('screen', 'form')
    const place = await d.find('input[name="place"][value="spacecraft"]')
    await d.sleep(600)
    d.click(place)
    await d.sleep(700)
    const oxygen = await d.find('#oxygen')
    await d.scrollTo(oxygen, 230)
    await d.type(oxygen, DEMO.oxygen, 170)
    await d.sleep(350)
    await d.type(await d.find('#pressure'), DEMO.pressure, 140)
    await d.sleep(450)
    const solid = await d.find('input[name="fuel_phase"][value="solid"]')
    await d.scrollTo(solid, 300)
    d.click(solid)
    await d.sleep(650)
    const submit = await d.find('button', { text: 'Compare investigations' })
    await d.scrollTo(submit, 460)
    await d.sleep(450)
    d.click(submit) // the real form opens the real comparison
    setPhase('screen', 'screen')
    await d.find('.ranked-row', { timeout: 12000 })
    await d.sleep(1600) // the scenario as the site read it
    await d.scrollTo(await d.find('h2', { text: 'Ranked' }), 90)
    await d.sleep(2000)
    await addThird(d)
    setPhase('screen', 'lanes')
    await d.sleep(3600)
  },

  async visualize(d, setPhase, end) {
    setPhase('screen', end ? 'chart' : 'screen')
    if (!(d.path() || '').startsWith('/visualization')) await d.go(DEMO.visualizationPath)
    if (!d.sameOrigin) return
    // The page keeps its scenario bar in view below the site's header; headings scroll in under both.
    const below = 270
    const probe = await d.find('#probe-oxygen', { timeout: 9000 })
    const where = await d.find('h3', { text: 'Where the tests sit', timeout: 15000 }) // the charts' data has loaded
    if (end) {
      d.setValue(probe, '0.3')
      await d.scrollTo(await d.find('h3', { text: 'How many NASA tests' }), below)
      return
    }
    await d.sleep(1400)
    await d.scrollTo(where, below)
    setPhase('screen', 'chart')
    await d.sleep(1300)
    for (const value of ['0.22', '0.23', '0.24', '0.25', '0.26', '0.27', '0.28', '0.29', '0.3']) {
      d.setValue(probe, value) // move the real scenario slider; every chart's crosshair follows
      await d.sleep(220)
    }
    await d.sleep(3000)
    await d.scrollTo(await d.find('h3', { text: 'How many NASA tests' }), below)
    await d.sleep(4400)
    await d.scrollTo(await d.find('h3', { text: 'FLEX: droplet burning rate' }), below)
    setPhase('screen', 'screen')
    await d.sleep(3600)
  },

  async assistant(d, setPhase, end) {
    if (end) {
      if (!(d.path() || '').startsWith('/assistant')) await d.go('/assistant')
      setPhase('pullback')
      return
    }
    setPhase('screen', 'screen')
    await d.go('/assistant')
    if (!d.sameOrigin) {
      await d.sleep(7000)
      setPhase('pullback')
      return
    }
    const box = await d.find('#question', { timeout: 9000 })
    await d.sleep(800)
    await d.type(box, DEMO.question, 40)
    await d.sleep(500)
    d.click(await d.find('button', { text: 'Ask' })) // a real question to the real assistant
    const asked = Date.now()
    await d.scrollTo(await d.find('section.answer', { timeout: 3000 }), 200)
    setPhase('screen', 'answer')
    const answer = await d.find('.answer-meta, .answer-notice, .api-error', { timeout: 26000 })
    if (answer) await d.scrollTo(answer, 90)
    const waited = Date.now() - asked
    await d.sleep(Math.max(3000, 7000 - Math.max(0, waited - 12000))) // read time, shorter when the answer was slow
    setPhase('pullback')
  },
}

