// ============================================================================
// Hooks
// ============================================================================

function usePrefersReducedMotion() {
  const query = '(prefers-reduced-motion: reduce)'
  const [reduced, setReduced] = useState(() => typeof window !== 'undefined' && Boolean(window.matchMedia && window.matchMedia(query).matches))
  useEffect(() => {
    if (!window.matchMedia) return undefined
    const mq = window.matchMedia(query)
    const update = () => setReduced(mq.matches)
    update()
    if (mq.addEventListener) mq.addEventListener('change', update)
    return () => {
      if (mq.removeEventListener) mq.removeEventListener('change', update)
    }
  }, [])
  return reduced
}

/** Same-origin when this page is served by the site itself (or by present.mjs in front of it). */
function useSite() {
  const [site, setSite] = useState(null)
  useEffect(() => {
    let alive = true
    const crossOrigin = { base: SITE_URL, sameOrigin: false }
    if (!/^https?:$/.test(window.location.protocol)) {
      setSite(crossOrigin)
      return undefined
    }
    fetch('/api/health', { headers: { Accept: 'application/json' } })
      .then((res) => (res.ok ? res.json() : null))
      .then((body) => alive && setSite(body && body.investigations ? { base: '', sameOrigin: true } : crossOrigin))
      .catch(() => alive && setSite(crossOrigin))
    return () => {
      alive = false
    }
  }, [])
  return site
}

const fullscreenElement = () => document.fullscreenElement || document.webkitFullscreenElement || null

