// ============================================================================

export default function FlareOpening() {
  // index: the beat; mode: 'play' runs the slide's sequence, 'end' shows its finished state;
  // phase: position in the sequence; focus: where the camera looks on the laptop screen;
  // token: identifies one visit, so stale timers and demos do nothing.
  const [nav, setNav] = useState({ index: 0, mode: 'play', phase: 0, token: 0, costShown: false, focus: 'screen' })
  const [dipKey, setDipKey] = useState(0)
  const [presentMode, setPresentMode] = useState(false)
  const [fullscreen, setFullscreen] = useState(false)
  const [idle, setIdle] = useState(false)
  const [textWidth, setTextWidth] = useState(ESTIMATED_TEXT_WIDTH)
  const [stageScale, setStageScale] = useState(1)
  const reduced = usePrefersReducedMotion()
  const site = useSite()
  const rootRef = useRef(null)
  const stageRef = useRef(null)
  const wordRef = useRef(null)
  const frameRef = useRef(null)
  const keyRef = useRef(null)
  const presenting = presentMode || fullscreen
  const beat = BEATS[nav.index]
  const timeline = TIMELINES[beat.id]
  const phase = timeline[Math.min(nav.phase, timeline.length - 1)].phase

  const next = useCallback(
    () =>
      setNav((n) => {
        if (n.index === 0 && n.costShown) return enterBeat(n, 2, 'play') // the cost is already on screen
        return n.index < LAST ? enterBeat(n, n.index + 1, 'play') : n
      }),
    [],
  )
  const prev = useCallback(() => setNav((n) => (n.index > 0 ? enterBeat(n, n.index - 1, 'end') : n)), [])
  const home = useCallback(() => setNav((n) => enterBeat(n, 0, 'play')), [])
  const end = useCallback(() => setNav((n) => enterBeat(n, LAST, 'end')), [])

  // Timed sequences and the cost reveal. These timers only move the phase inside the
  // current slide; they never change the slide.
  useEffect(() => {
    const { token, index, mode } = nav
    const id = BEATS[index].id
    const timers = []
    const later = (ms, update) => timers.push(window.setTimeout(() => setNav((n) => (n.token === token ? update(n) : n)), ms))
    if (mode === 'play') {
      TIMELINES[id].forEach((step, i) => {
        if (i > 0 && step.at != null) later(step.at * TIMING.sequenceScale, (n) => ({ ...n, phase: Math.max(n.phase, i) }))
      })
    }
    if (id === 'apollo' && TIMING.costReveal != null) later(TIMING.costReveal, (n) => ({ ...n, costShown: true }))
    return () => timers.forEach((t) => window.clearTimeout(t))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nav.token])

  // The website slides: run the demo on the real site in the frame.
  useEffect(() => {
    const demo = SITE_DEMOS[BEATS[nav.index].id]
    if (!demo || !site) return undefined
    const token = nav.token
    let alive = true
    const setPhase = (name, focus) =>
      setNav((n) => {
        if (n.token !== token) return n
        const i = TIMELINES[BEATS[n.index].id].findIndex((s) => s.phase === name)
        return i < 0 ? n : { ...n, phase: i, focus: focus || n.focus }
      })
    const driver = makeDriver({ frame: () => frameRef.current, base: site.base, sameOrigin: site.sameOrigin, alive: () => alive })
    demo(driver, setPhase, nav.mode === 'end').catch(() => {
      // Cancelled by the presenter moving on, or the site did not answer: the slide stays as it is.
    })
    return () => {
      alive = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nav.token, site])

  // Reduced motion: a short dip to navy covers each change of shot.
  const shot = SHOT[phase]
  const firstShot = useRef(shot)
  useEffect(() => {
    if (shot !== firstShot.current) {
      firstShot.current = null
      setDipKey((k) => k + 1)
    }
  }, [shot])

  // The website frame is laid out in stage units; keep it scaled with the stage.
  useLayoutEffect(() => {
    const el = stageRef.current
    if (!el) return undefined
    const update = () => setStageScale(el.clientWidth / W)
    update()
    if (typeof ResizeObserver === 'undefined') return undefined
    const observer = new ResizeObserver(update)
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  // Place the flame mark beside the real width of the wordmark, once fonts are in.
  useLayoutEffect(() => {
    const fonts = typeof document !== 'undefined' ? document.fonts : null
    let alive = true
    const measure = () => {
      const el = wordRef.current
      if (!alive || !el) return
      const width = el.getComputedTextLength()
      if (width > 0) setTextWidth((w) => (Math.abs(w - width) > 0.5 ? width : w))
    }
    measure()
    if (fonts && fonts.ready) fonts.ready.then(measure)
    if (fonts && fonts.addEventListener) fonts.addEventListener('loadingdone', measure)
    return () => {
      alive = false
      if (fonts && fonts.removeEventListener) fonts.removeEventListener('loadingdone', measure)
    }
  }, [])

  const toggleFullscreen = useCallback(() => {
    try {
      if (fullscreenElement()) {
        const exit = document.exitFullscreen || document.webkitExitFullscreen
        const result = exit ? exit.call(document) : null
        if (result && result.catch) result.catch(() => {})
        return
      }
      const el = rootRef.current
      const request = el && (el.requestFullscreen || el.webkitRequestFullscreen)
      if (!request || document.fullscreenEnabled === false) return
      const result = request.call(el)
      if (result && result.catch) result.catch(() => {})
    } catch {
      // Blocked, for example inside an iframe: carry on without it.
    }
  }, [])

  useEffect(() => {
    const sync = () => setFullscreen(Boolean(fullscreenElement()))
    document.addEventListener('fullscreenchange', sync)
    document.addEventListener('webkitfullscreenchange', sync)
    return () => {
      document.removeEventListener('fullscreenchange', sync)
      document.removeEventListener('webkitfullscreenchange', sync)
    }
  }, [])

  // Presenter keys. Key repeat is ignored so holding a key never skips a beat.
  useEffect(() => {
    const onKey = (event) => {
      if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return
      const target = event.target
      const onControl = target && target.closest && target.closest('button, a, input, select, textarea, [contenteditable="true"]')
      const key = event.key
      if ((key === 'Enter' || key === ' ' || key === 'Spacebar') && onControl) return // the focused button handles it
      let handled = true
      switch (key) {
        case 'ArrowRight':
        case 'PageDown':
        case ' ':
        case 'Spacebar':
        case 'Enter':
          if (!event.repeat) next()
          break
        case 'ArrowLeft':
        case 'PageUp':
          if (!event.repeat) prev()
          break
        case 'Home':
          home()
          break
        case 'End':
          end()
          break
        case 'f':
        case 'F':
          if (!event.repeat) toggleFullscreen()
          break
        case 'h':
        case 'H':
          if (!event.repeat) setPresentMode((on) => !on)
          break
        default:
          handled = false
      }
      if (handled) event.preventDefault()
    }
    keyRef.current = onKey
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [next, prev, home, end, toggleFullscreen])

  // If the website ever takes keyboard focus, its keys still reach the presenter's controls.
  const onFrameLoad = useCallback(() => {
    try {
      const w = frameRef.current && frameRef.current.contentWindow
      if (w && !w.__flareKeys) {
        w.__flareKeys = true
        w.addEventListener('keydown', (event) => {
          if (['ArrowRight', 'ArrowLeft', 'PageDown', 'PageUp', 'Home', 'End'].includes(event.key) && keyRef.current) keyRef.current(event)
        })
      }
    } catch {
      // Cross-origin: the frame never receives focus anyway.
    }
  }, [])

  // Presentation mode: hide the controls and cursor after a still moment. This timer only
  // changes what the presenter sees; it never touches the story.
  useEffect(() => {
    if (!presenting) {
      setIdle(false)
      return undefined
    }
    let timer = 0
    const wake = () => {
      setIdle(false)
      window.clearTimeout(timer)
      timer = window.setTimeout(() => setIdle(true), TIMING.idleHide)
    }
    wake()
    window.addEventListener('mousemove', wake)
    return () => {
      window.clearTimeout(timer)
      window.removeEventListener('mousemove', wake)
    }
  }, [presenting])

  const layout = markLayout(textWidth)
  const v = deriveScene(phase, { layout, reduced, costShown: nav.costShown, focus: nav.focus })
  const release = (event) => {
    if (event.detail > 0) event.currentTarget.blur() // a mouse click leaves no focused button behind
  }
  const shownBeat = nav.index === 0 && nav.costShown ? 1 : nav.index
  // Slide 7 shows the team's own logo and the real QR code; the SI illustration leaves with the warp.
  const credit = beat.slide === 1 ? TEXT.photoCredit : beat.slide === 7 && phase !== 'warp' ? '' : TEXT.watermark
  const label = nav.index === 0 && v.costVisible ? BEATS[1].label : beat.label

  return (
    <div
      ref={rootRef}
      className="fo-root"
      data-beat={beat.id}
      data-phase={phase}
      data-slide={beat.slide}
      data-cost={v.costVisible ? 'shown' : 'hidden'}
      data-focus={nav.focus}
      data-site={site ? (site.sameOrigin ? 'same-origin' : 'cross-origin') : 'pending'}
      data-presenting={presenting ? 'true' : 'false'}
      data-idle={presenting && idle ? 'true' : 'false'}
      style={{ '--calm': reduced ? 1.8 : 1 }}
    >
      <style>{CSS}</style>
      <div className="fo-stage" ref={stageRef}>
        <svg className="fo-svg" viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="xMidYMid meet" aria-hidden="true" focusable="false">
          <Defs v={v} />
          <rect width={W} height={H} fill="url(#fo-sky)" />

          <g data-layer="backdrop" style={v.backdrop}>
            <g opacity="0.5">
              <StarLayer stars={BACKDROP_STARS} seconds={520} />
            </g>
          </g>

          <g data-layer="stars" style={v.stars}>
            {STAR_LAYERS.map((layer) => (
              <StarLayer key={layer.seconds} stars={layer.stars} seconds={layer.seconds} />
            ))}
          </g>

          <g data-layer="exterior" style={v.exterior}>
            <g data-layer="earthCam" style={v.earth}>
              <Earth />
            </g>
            <g data-layer="stationCam" style={v.station}>
              <Station />
            </g>
          </g>

          <ApolloCrew style={v.apollo} shift={v.apolloShift} />
          <Cost style={v.cost} />

          <g className="fo-amb fo-shake" style={{ '--d': '0.9s', '--shake': v.shake }}>
            <g data-layer="interior" style={v.interior}>
              <g data-layer="interiorCam" style={v.interiorCam}>
                <Interior pose={v.pose} v={v} />
              </g>
            </g>

            <g data-layer="flame" style={v.flame}>
              <Fire v={v} />
            </g>

            <rect data-layer="vignette" width={W} height={H} fill="url(#fo-vignette)" style={v.vignette} />
          </g>

          <g data-layer="lift" style={v.lift}>
            <g data-layer="wordmark" style={v.wordmark}>
              <text ref={wordRef} x={layout.textX} y={WORD.baseline} fontSize={WORD.size} fontWeight="900" fill={COLORS.text} style={{ fontFamily: FONTS.display, letterSpacing: `${WORD.tracking}em` }}>
                {TEXT.title}
              </text>
            </g>
          </g>

          <g data-layer="subtitle" style={v.subtitle}>
            <text x={CX} y="530" textAnchor="middle" fontSize="38" fontWeight="400" fill={COLORS.textSoft} style={{ fontFamily: FONTS.text, letterSpacing: '0.02em' }}>
              {TEXT.subtitle}
            </text>
          </g>

          <g data-layer="tagline" style={v.tagline}>
            <text x={CX} y="588" textAnchor="middle" fontSize="28" fontWeight="300" fontStyle="italic" fill={COLORS.text} opacity="0.9" style={{ fontFamily: FONTS.text }}>
              {TEXT.tagline}
            </text>
          </g>

          {phase === 'warp' && !reduced && <Warp />}
          <TeamReveal v={v} drawing={phase === 'ring' && !reduced} />

          {reduced && dipKey > 0 && <rect key={dipKey} className="fo-dip" width={W} height={H} fill={COLORS.skyTop} />}
        </svg>

        <SiteScreen v={v} frameRef={frameRef} src={site ? `${site.base}/` : null} stageScale={stageScale} onFrameLoad={onFrameLoad} />

        {credit && <span className="fo-watermark">{credit}</span>}

        <div className="fo-hud">
          <div className="fo-progress">
            <span className="fo-scene">{beat.scene}</span>
            <span className="fo-dots" aria-hidden="true">
              {SLIDE_GROUPS.map((group) => (
                <span key={group.slide} className="fo-group">
                  {group.beats.map((i) => (
                    <span key={i} className="fo-dot" data-state={i === shownBeat ? 'current' : i < shownBeat ? 'done' : 'todo'} />
                  ))}
                </span>
              ))}
            </span>
            <span className="fo-count">
              {beat.slide} / {SLIDE_COUNT}
            </span>
          </div>
          <p className="fo-hint">{hintFor(beat.id, nav.costShown)}</p>
          <div className="fo-buttons">
            <button
              type="button"
              className="fo-btn"
              data-control="prev"
              aria-label="Previous"
              disabled={nav.index === 0}
              onClick={(event) => {
                prev()
                release(event)
              }}
            >
              <Icon d={ICONS.prev} />
              <span>Previous</span>
            </button>
            <button
              type="button"
              className="fo-btn fo-btn-next"
              data-control="next"
              aria-label="Next"
              disabled={nav.index === LAST}
              onClick={(event) => {
                next()
                release(event)
              }}
            >
              <span>Next</span>
              <Icon d={ICONS.next} />
            </button>
            <button
              type="button"
              className="fo-btn fo-btn-icon"
              data-control="fullscreen"
              aria-label={fullscreen ? 'Exit full screen' : 'Full screen'}
              title="Full screen (F)"
              onClick={(event) => {
                toggleFullscreen()
                release(event)
              }}
            >
              <Icon d={fullscreen ? ICONS.shrink : ICONS.expand} />
            </button>
          </div>
        </div>
      </div>
      <p className="fo-sr" aria-live="polite">{`Slide ${beat.slide} of ${SLIDE_COUNT}: ${label}`}</p>
    </div>
  )
}
